-- seed_retroplanning_items_mariage.sql
-- Injecte le rétroplanning de préparation sur 1561 items de checklist
-- (source : missions_checklist_retroplanning_v1.csv, lignes avec code jalon).
--   · milestone_id     ← jalon J1..J12 (milestones.sort_order)
--   · ideal_start_date ← « Début idéal »  (requiert migration 0142)
--   · target_date      ← « Date cible »
--   · deadline_date    ← « Date limite »
--   · criticality      ← « Criticité »
-- Correspondance par (pôle, titre de mission, libellé d'item).
-- Les items sans jalon (Jour J, Après…) ne sont pas modifiés.
-- Bloc DO unique : atomique (toute erreur annule tout), idempotent.
-- Lancer dans l'éditeur SQL Supabase.

do $$
declare n_bad int; n_upd int;
begin
  create temp table _retro (pole text, mission text, label text, jalon int,
    ideal_start date, target date, deadline date, criticality text) on commit drop;


  -- Garde-fou : chaque ligne doit correspondre à exactement un item.
  select count(*) into n_bad from (
    select r.pole, r.mission, r.label
    from _retro r
    left join public._20270628_poles p           on p.name = r.pole
    left join public._20270628_domaines d        on d.pole_id = p.id
    left join public._20270628_missions m        on m.domaine_id = d.id and m.title = r.mission
    left join public._20270628_checklists c      on c.owner_type = 'mission' and c.owner_id = m.id
    left join public._20270628_checklist_items i on i.checklist_id = c.id and i.label = r.label
    group by r.pole, r.mission, r.label
    having count(i.id) <> 1
  ) x;
  if n_bad > 0 then
    raise exception '% ligne(s) sans correspondance unique — rien n''est modifié', n_bad;
  end if;

  if exists (select 1 from _retro r
             where not exists (select 1 from public._20270628_milestones ms where ms.sort_order = r.jalon)) then
    raise exception 'Jalon(s) manquant(s) dans _20270628_milestones — lancer seed_milestones_mariage.sql';
  end if;

  update public._20270628_checklist_items i
  set milestone_id     = ms.id,
      ideal_start_date = r.ideal_start,
      target_date      = r.target,
      deadline_date    = r.deadline,
      criticality      = r.criticality
  from _retro r
  join public._20270628_poles p       on p.name = r.pole
  join public._20270628_domaines d    on d.pole_id = p.id
  join public._20270628_missions m    on m.domaine_id = d.id and m.title = r.mission
  join public._20270628_checklists c  on c.owner_type = 'mission' and c.owner_id = m.id
  join public._20270628_milestones ms on ms.sort_order = r.jalon
  where i.checklist_id = c.id and i.label = r.label;

  get diagnostics n_upd = row_count;
  if n_upd <> 1561 then
    raise exception '% items mis à jour au lieu de 1561 — annulé', n_upd;
  end if;
  raise notice '% items mis à jour', n_upd;
end $$;

-- Contrôle : répartition par jalon (attendu : 1561 items au total)
select ms.sort_order, ms.name, count(i.id) as items,
       count(*) filter (where i.criticality = 'blocking') as blocking
from public._20270628_milestones ms
left join public._20270628_checklist_items i on i.milestone_id = ms.id
group by ms.sort_order, ms.name
order by ms.sort_order;
